@Component
public class AuthInterceptor implements HandlerInterceptor {
    @Autowired TokenService tokens;                       // 可注入 Spring Bean
    public boolean preHandle(HttpServletRequest req, HttpServletResponse resp, Object handler) {
        if (handler instanceof HandlerMethod hm && hm.hasMethodAnnotation(Anonymous.class)) return true;
        UserCtx.set(tokens.verify(req.getHeader("Authorization")));
        return true;
    }
    public void afterCompletion(HttpServletRequest r, HttpServletResponse s, Object h, Exception e) {
        UserCtx.clear();                                  // 清理 ThreadLocal
    }
}
