@Configuration @EnableAsync
class AsyncConfig implements AsyncConfigurer {
    @Bean("orderExecutor")
    public ThreadPoolTaskExecutor orderExecutor() {
        ThreadPoolTaskExecutor e = new ThreadPoolTaskExecutor();
        e.setCorePoolSize(8); e.setMaxPoolSize(16); e.setQueueCapacity(500);
        e.setThreadNamePrefix("order-async-");
        e.setTaskDecorator(r -> { var mdc = MDC.getCopyOfContextMap();
            return () -> { if (mdc != null) MDC.setContextMap(mdc); try { r.run(); } finally { MDC.clear(); } }; });
        e.setWaitForTasksToCompleteOnShutdown(true); e.setAwaitTerminationSeconds(30);
        return e;
    }
    public AsyncUncaughtExceptionHandler getAsyncUncaughtExceptionHandler() {
        return (ex, m, args) -> log.error("async {} failed", m.getName(), ex);
    }
}
