public class RpcClientFactoryBean<T> implements FactoryBean<T> {
    private final Class<T> iface;
    public RpcClientFactoryBean(Class<T> iface) { this.iface = iface; }
    public T getObject() {
        return (T) Proxy.newProxyInstance(iface.getClassLoader(), new Class[]{iface},
            (p, m, args) -> rpc.invoke(iface.getName(), m.getName(), args));
    }
    public Class<?> getObjectType() { return iface; }
}
